import 'svelte/internal/disclose-version';
import 'svelte/internal/flags/legacy';
import * as $ from 'svelte/internal/client';

var root_1 = $.from_html(`<p class="auth-session-error"> </p>`);
var root_2 = $.from_html(`<p class="auth-session-loading">Loading sessions…</p>`);
var root_5 = $.from_html(`<button class="auth-session-revoke" type="button"> </button>`);
var root_4 = $.from_html(`<li class="auth-session-item"><div><p class="auth-session-meta"> </p> <p class="auth-session-sub"> </p></div> <!></li>`);
var root_3 = $.from_html(`<ul class="auth-session-list" aria-label="Active sessions"></ul>`);
var root_6 = $.from_html(`<p class="auth-session-empty">No sessions found.</p>`);
var root = $.from_html(`<div class="auth-session-manager"><!> <!></div>`);

export default function SessionManager($$anchor, $$props) {
	$.push($$props, false);

	let listEndpoint = $.prop($$props, 'listEndpoint', 8, "/auth/sessions");
	let revokeEndpoint = $.prop($$props, 'revokeEndpoint', 8, "/auth/sessions");
	let fetcher = $.prop($$props, 'fetcher', 8, fetch);
	let headers = $.prop($$props, 'headers', 24, () => ({}));
	let sessions = $.prop($$props, 'sessions', 12, null);
	let loading = $.mutable_source(false);
	let revokingId = $.mutable_source(null);
	let error = $.mutable_source(null);

	async function loadSessions() {
		$.set(loading, true);
		$.set(error, null);

		try {
			const response = await fetcher()(listEndpoint(), { headers: headers() });
			const data = await response.json();

			if (!response.ok || !data.ok) {
				throw new Error(data.error || "Failed to load sessions");
			}

			sessions(data.sessions);
		} catch(err) {
			$.set(error, err.message);
		} finally {
			$.set(loading, false);
		}
	}

	async function revoke(sessionId) {
		$.set(revokingId, sessionId);
		$.set(error, null);

		try {
			const response = await fetcher()(revokeEndpoint(), {
				method: "POST",
				headers: { "content-type": "application/json", ...headers() },
				body: JSON.stringify({ sessionId })
			});

			const data = await response.json();

			if (!response.ok || !data.ok) {
				throw new Error(data.error || "Failed to revoke session");
			}

			await loadSessions();
		} catch(err) {
			$.set(error, err.message);
		} finally {
			$.set(revokingId, null);
		}
	}

	if (!sessions()) {
		loadSessions();
	}

	$.init();

	var div = root();
	var node = $.child(div);

	{
		var consequent = ($$anchor) => {
			var p = root_1();
			var text = $.child(p, true);

			$.reset(p);
			$.template_effect(() => $.set_text(text, $.get(error)));
			$.append($$anchor, p);
		};

		$.if(node, ($$render) => {
			if ($.get(error)) $$render(consequent);
		});
	}

	var node_1 = $.sibling(node, 2);

	{
		var consequent_1 = ($$anchor) => {
			var p_1 = root_2();

			$.append($$anchor, p_1);
		};

		var consequent_3 = ($$anchor) => {
			var ul = root_3();

			$.each(ul, 5, sessions, $.index, ($$anchor, session) => {
				var li = root_4();
				var div_1 = $.child(li);
				var p_2 = $.child(div_1);
				var text_1 = $.child(p_2);

				$.reset(p_2);

				var p_3 = $.sibling(p_2, 2);
				var text_2 = $.child(p_3);

				$.reset(p_3);
				$.reset(div_1);

				var node_2 = $.sibling(div_1, 2);

				{
					var consequent_2 = ($$anchor) => {
						var button = root_5();
						var text_3 = $.child(button, true);

						$.reset(button);

						$.template_effect(() => {
							button.disabled = (
								$.get(revokingId),
								$.get(session),
								$.untrack(() => $.get(revokingId) === $.get(session).id)
							);

							$.set_attribute(button, 'aria-label', `Revoke session ${(
								$.get(session),
								$.untrack(() => $.get(session).ip || 'Unknown IP')
							) ?? ''}`);

							$.set_text(text_3, (
								$.get(revokingId),
								$.get(session),
								$.untrack(() => $.get(revokingId) === $.get(session).id ? 'Revoking…' : 'Revoke')
							));
						});

						$.event('click', button, () => revoke($.get(session).id));
						$.append($$anchor, button);
					};

					$.if(node_2, ($$render) => {
						if (($.get(session), $.untrack(() => !$.get(session).current))) $$render(consequent_2);
					});
				}

				$.reset(li);

				$.template_effect(
					($0) => {
						$.set_text(text_1, `${(
							$.get(session),
							$.untrack(() => $.get(session).current ? "Current session" : "Session")
						) ?? ''} ·
							${(
							$.get(session),
							$.untrack(() => $.get(session).ip || "Unknown IP")
						) ?? ''}`);

						$.set_text(text_2, `Expires ${$0 ?? ''}`);
					},
					[
						() => (
							$.get(session),
							$.untrack(() => new Date($.get(session).expiresAt).toLocaleString())
						)
					]
				);

				$.append($$anchor, li);
			});

			$.reset(ul);
			$.append($$anchor, ul);
		};

		var alternate = ($$anchor) => {
			var p_4 = root_6();

			$.append($$anchor, p_4);
		};

		$.if(node_1, ($$render) => {
			if ($.get(loading) && !sessions()) $$render(consequent_1); else if ((
				$.deep_read_state(sessions()),
				$.untrack(() => sessions() && sessions().length > 0)
			)) $$render(consequent_3, 1); else $$render(alternate, false);
		});
	}

	$.reset(div);
	$.append($$anchor, div);
	$.pop();
}