import 'svelte/internal/disclose-version';
import 'svelte/internal/flags/legacy';
import * as $ from 'svelte/internal/client';
import { auth } from "./auth-store.js";

export default function AuthGate($$anchor, $$props) {
	$.push($$props, false);

	const $auth = () => $.store_get(auth, '$auth', $$stores);
	const [$$stores, $$cleanup] = $.setup_stores();
	const resolvedUser = $.mutable_source();
	const resolvedLoading = $.mutable_source();
	let user = $.prop($$props, 'user', 8, undefined);
	let loading = $.prop($$props, 'loading', 8, undefined);
	let onUnauthenticated = $.prop($$props, 'onUnauthenticated', 8, null);

	$.legacy_pre_effect(() => ($.deep_read_state(user()), $auth()), () => {
		$.set(resolvedUser, user() ?? $auth().user ?? null);
	});

	$.legacy_pre_effect(() => ($.deep_read_state(loading()), $auth()), () => {
		$.set(resolvedLoading, loading() ?? $auth().loading ?? false);
	});

	$.legacy_pre_effect(
		() => (
			$.get(resolvedLoading),
			$.get(resolvedUser),
			$.deep_read_state(onUnauthenticated())
		),
		() => {
			if (!$.get(resolvedLoading) && !$.get(resolvedUser) && typeof onUnauthenticated() === "function") {
				onUnauthenticated()();
			}
		}
	);

	$.legacy_pre_effect_reset();
	$.init();

	var fragment = $.comment();
	var node = $.first_child(fragment);

	{
		var consequent = ($$anchor) => {
			var fragment_1 = $.comment();
			var node_1 = $.first_child(fragment_1);

			$.slot(node_1, $$props, 'loading', {}, ($$anchor) => {
				var text = $.text('Loading…');

				$.append($$anchor, text);
			});

			$.append($$anchor, fragment_1);
		};

		var consequent_1 = ($$anchor) => {
			var fragment_2 = $.comment();
			var node_2 = $.first_child(fragment_2);

			$.slot(node_2, $$props, 'default', {}, null);
			$.append($$anchor, fragment_2);
		};

		var alternate = ($$anchor) => {
			var fragment_3 = $.comment();
			var node_3 = $.first_child(fragment_3);

			$.slot(node_3, $$props, 'unauthenticated', {}, ($$anchor) => {
				var text_1 = $.text('Sign in required.');

				$.append($$anchor, text_1);
			});

			$.append($$anchor, fragment_3);
		};

		$.if(node, ($$render) => {
			if ($.get(resolvedLoading)) $$render(consequent); else if ($.get(resolvedUser)) $$render(consequent_1, 1); else $$render(alternate, false);
		});
	}

	$.append($$anchor, fragment);
	$.pop();
	$$cleanup();
}