import 'AuthNotification.svelte.css';import 'svelte/internal/disclose-version';
import * as $ from 'svelte/internal/client';

var root_2 = $.from_html(`<button type="button" class="cta-button svelte-z3i0j9"> </button>`);
var root_1 = $.from_html(`<div class="auth-notification svelte-z3i0j9" role="alert"><div class="notification-content svelte-z3i0j9"><div class="notification-icon svelte-z3i0j9"><span>✓</span></div> <div class="notification-body svelte-z3i0j9"><h3 class="svelte-z3i0j9"> </h3> <p class="svelte-z3i0j9"> </p> <!></div> <button type="button" class="close-button svelte-z3i0j9" aria-label="Close notification">×</button></div></div>`);

export default function AuthNotification($$anchor, $$props) {
	$.push($$props, true);

	let visible = $.prop($$props, 'visible', 15, false),
		title = $.prop($$props, 'title', 3, 'Notice'),
		message = $.prop($$props, 'message', 3, ''),
		onClose = $.prop($$props, 'onClose', 3, () => {}),
		ctaLabel = $.prop($$props, 'ctaLabel', 3, null),
		onCta = $.prop($$props, 'onCta', 3, () => {});

	function close() {
		visible(false);
		onClose()();
	}

	var fragment = $.comment();
	var node = $.first_child(fragment);

	{
		var consequent_1 = ($$anchor) => {
			var div = root_1();
			var div_1 = $.child(div);
			var div_2 = $.sibling($.child(div_1), 2);
			var h3 = $.child(div_2);
			var text = $.child(h3, true);

			$.reset(h3);

			var p = $.sibling(h3, 2);
			var text_1 = $.child(p, true);

			$.reset(p);

			var node_1 = $.sibling(p, 2);

			{
				var consequent = ($$anchor) => {
					var button = root_2();
					var text_2 = $.child(button, true);

					$.reset(button);
					$.template_effect(() => $.set_text(text_2, ctaLabel()));

					$.delegated('click', button, function (...$$args) {
						onCta()?.apply(this, $$args);
					});

					$.append($$anchor, button);
				};

				$.if(node_1, ($$render) => {
					if (ctaLabel()) $$render(consequent);
				});
			}

			$.reset(div_2);

			var button_1 = $.sibling(div_2, 2);

			$.reset(div_1);
			$.reset(div);

			$.template_effect(() => {
				$.set_text(text, title());
				$.set_text(text_1, message());
			});

			$.delegated('click', button_1, close);
			$.append($$anchor, div);
		};

		$.if(node, ($$render) => {
			if (visible()) $$render(consequent_1);
		});
	}

	$.append($$anchor, fragment);
	$.pop();
}

$.delegate(['click']);